<script setup>
import {computed,ref,onMounted,watch} from 'vue'
import {useArcade} from '../stores/arcade'
import {skins} from '../data/skins'
const emit=defineEmits(['close']),s=useArcade(),dialog=ref(null),selected=ref(s.skin?.id??'default'),busy=ref(false),error=ref(''),notice=ref(''),confirm=ref(false)
const options=computed(()=>[{id:'default',stage:s.partner.stage,name:'기본 스킨',image:s.partner.image,price:0},...skins.filter(x=>x.character===s.partner.id).sort((a,b)=>(a.stage===s.partner.stage?0:1)-(b.stage===s.partner.stage?0:1)||a.stage-b.stage)]),choice=computed(()=>options.value.find(x=>x.id===selected.value)??options.value[0]),locked=computed(()=>choice.value.id!=='default'&&choice.value.stage!==s.partner.stage),owned=computed(()=>choice.value.id==='default'||s.data.pet.ownedSkins?.includes(choice.value.id)),equipped=computed(()=>!locked.value&&(s.skin?.id??'default')===choice.value.id)
watch(()=>[s.partner.id,s.partner.stage],()=>{selected.value=s.skin?.id??'default';confirm.value=false})
onMounted(()=>dialog.value.showModal())
function select(id){if(busy.value)return;selected.value=id;confirm.value=false;error.value='';notice.value=''}
async function apply(){if(busy.value||equipped.value||locked.value)return;if(!owned.value&&!confirm.value){confirm.value=true;return}busy.value=true;error.value='';try{await s.petAction('skin',choice.value.id);notice.value=choice.value.name+' 적용 완료!';confirm.value=false}catch(e){error.value=e.message}finally{busy.value=false}}
function close(){if(!busy.value){dialog.value.close();emit('close')}}
</script>
<template><dialog ref="dialog" class="skin-shop" aria-labelledby="skin-title" @cancel.prevent="close"><div class="skin-shop-heading"><div><small>SPOKEMON / SKIN COLLECTION</small><h2 id="skin-title">{{s.partner.name}} 스킨 상점</h2></div><button type="button" class="light" aria-label="스킨 상점 닫기" :disabled="busy" @click="close">✕</button></div><p class="skin-shop-note">현재 강화 {{s.partner.stage}}단계 · 1단계 500P / 2단계 1,000P / 3단계 1,500P<br/>현재 단계 스킨만 착용 가능 · 구매한 스킨 재적용은 무료입니다.</p><div class="skin-shop-body"><div class="skin-preview"><div class="skin-preview-art"><img :src="choice.image" :alt="choice.name"/><div v-if="locked" class="skin-lock-screen" aria-label="스킨 잠김"><span>🔒</span><b>{{choice.stage<s.partner.stage?'이전 단계 스킨 잠김':'강화 '+choice.stage+'단계 필요'}}</b></div></div><h3>{{choice.name}}</h3><p>{{choice.id==='default'?'무료':choice.price.toLocaleString()+' P'}} · 보유 {{s.data.coins.toLocaleString()}} P</p><p class="skin-shop-note">돌보기 화면 가운데 포켓몬에만 적용돼요. 스킨은 보관되지만 다른 강화 단계에서는 착용할 수 없습니다.</p></div><div class="skin-options" aria-label="구매 가능한 스킨"><button v-for="skin in options" :key="skin.id" type="button" :class="['skin-option',{selected:selected===skin.id,locked:skin.id!=='default'&&skin.stage!==s.partner.stage}]" :aria-pressed="selected===skin.id" :aria-label="skin.name+(skin.id!=='default'&&skin.stage!==s.partner.stage?' · 잠김':'')" :disabled="busy" @click="select(skin.id)"><div class="skin-option-art"><img :src="skin.image" :alt="skin.name"/><span v-if="skin.id!=='default'&&skin.stage!==s.partner.stage" class="skin-tile-lock" aria-hidden="true">🔒</span></div><b>{{skin.name}}</b><small>{{skin.id==='default'?'기본 모습':'강화 '+skin.stage+'단계 · '+skin.price.toLocaleString()+' P'}}</small><small>{{skin.id!=='default'&&skin.stage!==s.partner.stage?'착용 잠김':(s.skin?.id??'default')===skin.id?'✓ 적용 중':skin.id==='default'||s.data.pet.ownedSkins?.includes(skin.id)?'보유 · 무료 적용':'구매 가능'}}</small></button></div></div><div class="skin-shop-action"><p v-if="confirm" role="status">{{choice.name}} 구매에 {{choice.price.toLocaleString()}} P를 사용할까요? 구매 후 {{(s.data.coins-choice.price).toLocaleString()}} P</p><button :disabled="busy||locked||equipped||(!owned&&s.data.coins<choice.price)" @click="apply">{{busy?'처리 중…':locked?'🔒 현재 단계만 착용 가능':equipped?'✓ 적용 중':owned?'무료로 적용하기':confirm?choice.price.toLocaleString()+' P 사용하고 구매 확정':choice.price.toLocaleString()+' P로 구매·적용'}}</button><button v-if="confirm" class="light" :disabled="busy" @click="confirm=false">취소</button><p v-if="!locked&&!owned&&s.data.coins<choice.price">포인트가 부족해요. 퀴즈를 풀어 모아 보세요!</p><p v-if="notice" role="status">{{notice}}</p><p v-if="error" role="alert">{{error}}</p></div></dialog></template>
<style scoped>
.skin-shop{box-sizing:border-box;width:min(880px,calc(100vw - 24px));max-width:none;max-height:90dvh;padding:20px;overflow:auto;border:3px solid var(--rpg-edge);border-radius:18px;background:var(--rpg-paper);color:var(--rpg-ink);box-shadow:inset 0 0 0 4px var(--rpg-bright),0 8px 0 var(--rpg-shadow),0 20px 60px #0005}.skin-shop::backdrop{background:#152539b3;backdrop-filter:blur(4px)}.skin-shop-heading{display:flex;justify-content:space-between;gap:12px;align-items:center}.skin-shop-heading h2{font-size:23px;margin:6px 0}.skin-shop-heading small{font-size:10px;color:var(--rpg-edge)}.skin-shop-body{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.5fr);gap:20px;align-items:start}.skin-preview{text-align:center;background:var(--rpg-soft);padding:12px;border:2px solid var(--rpg-mid);border-radius:12px;position:sticky;top:0}.skin-preview-art{position:relative}.skin-preview-art>img{width:100%;height:230px;object-fit:contain;background:#fff;border-radius:9px}.skin-preview h3{font-size:18px;margin:12px 0}.skin-options{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.skin-option{min-width:0;display:flex;flex-direction:column;align-items:stretch;gap:6px;padding:8px!important;background:var(--rpg-paper)!important;color:var(--rpg-ink)!important;border:2px solid var(--rpg-edge)!important}.skin-option.selected{background:var(--rpg-soft)!important;outline:3px solid var(--rpg-mid);outline-offset:1px}.skin-option-art{position:relative}.skin-option-art img{display:block;width:100%;height:115px;object-fit:contain;background:#fff;border-radius:5px}.skin-option.locked img{filter:grayscale(.65);opacity:.45}.skin-tile-lock{position:absolute;inset:0;display:grid;place-items:center;font-size:34px;background:#25334d30;border-radius:5px}.skin-lock-screen{position:absolute;inset:0;display:flex;flex-direction:column;gap:12px;justify-content:center;align-items:center;background:#25334da8;backdrop-filter:blur(2px);border-radius:9px;color:#fff}.skin-lock-screen>span{font-size:45px}.skin-lock-screen>b{font-size:14px}.skin-option b{font-size:12px}.skin-option small{font-size:10px}.skin-shop-note{font-size:11px;line-height:1.7}.skin-shop-action{position:sticky;bottom:-20px;background:var(--rpg-paper);padding:14px 0 6px;border-top:2px solid var(--rpg-mid);margin-top:16px}.skin-shop-action p{font-size:12px}.skin-shop-action button{margin:0 8px 4px 0}.skin-shop button{touch-action:manipulation}@media(max-width:600px){.skin-shop{padding:14px;max-height:92dvh}.skin-shop-body{grid-template-columns:1fr}.skin-preview{position:static}.skin-preview-art>img{height:140px}.skin-preview .skin-shop-note{display:none}.skin-shop-heading h2{font-size:18px}.skin-options{grid-template-columns:repeat(2,minmax(0,1fr))}.skin-option-art img{height:105px}.skin-shop-action{bottom:-14px}.skin-shop-note{margin:8px 0}}
</style>
